  requests: { label: 'Requests',   get: (st, m) => String(Number(m.requests) || 0) },
  latency:  { label: 'p95 speed',  get: (st, m) => (m.latency_p95_ms ? (m.latency_p95_ms / 1000).toFixed(1) + 's' : '-') },
